def match_parens(lst):
    def analyze(s):
        balance = 0
        min_prefix = 0
        for c in s:
            if c == '(':
                balance += 1
            else:
                balance -= 1
            if balance < min_prefix:
                min_prefix = balance
        return balance, min_prefix

    b1, mp1 = analyze(lst[0])
    b2, mp2 = analyze(lst[1])

    if b1 + b2 != 0:
        return 'No'

    # Check lst[0] + lst[1]
    if mp1 >= 0 and b1 + mp2 >= 0:
        return 'Yes'

    # Check lst[1] + lst[0]
    if mp2 >= 0 and b2 + mp1 >= 0:
        return 'Yes'

    return 'No'
